"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[260],{40294:e=>{e.exports=JSON.parse('{"functions":[{"name":"struct","desc":"Type declaration. `class` is a synonym of `struct`.\\n\\n**Syntax:** `struct LeaderstatsServer { Janitor* janitor; };`\\n\\n**Emit:** `export type` plus methods; field-only headers emit `const function Name()` with defaults.\\n\\nInstances are not RAII. Leaving a block does not `Destroy` \u2014 use Janitor.","params":[],"returns":[],"function_type":"static","source":{"line":23,"path":"moonwave/OOP.lua"}},{"name":"method","desc":"Method implementation.\\n\\n**Syntax:** `void Class::Method(T arg) { this.field = arg; }`\\n\\n**Emit:** `function Class:Method(arg: T)`\\n\\nUntagged files with only `Class::` `return` the table (ModuleScript).","params":[{"name":"arg","desc":"","lua_type":"any"}],"returns":[],"function_type":"static","source":{"line":37,"path":"moonwave/OOP.lua"}},{"name":"singleton","desc":"Construct **one** service in `init()` and use it from lambdas. That is the game singleton.\\n\\n**Syntax:** `void init() { LeaderstatsServer leaderstatsServer; }`","params":[],"returns":[],"function_type":"static","source":{"line":46,"path":"moonwave/OOP.lua"}},{"name":"access","desc":"Parsed and ignored. Luau has no access specifiers.\\n\\n**Syntax:** `public:` \xb7 `private:` \xb7 `protected:`\\n\\n**Emit:** omitted","params":[],"returns":[],"function_type":"static","source":{"line":57,"path":"moonwave/OOP.lua"}}],"properties":[],"types":[],"name":"OOP","desc":"Declare the type in a `.clh`. Implement `Class::Method` in the sibling `.clp` / `.clpp`.\\n\\n`this` is `self`. Bare fields become `self.field`. `public:` / `private:` are ignored.\\nThere is no `int main()` \u2014 Scripts use `void init()`.\\nStems must match: `LeaderstatsServer.clh` beside `LeaderstatsServer.server.clpp`.","source":{"line":11,"path":"moonwave/OOP.lua"}}')}}]);